-- Spoken-only RP for gestures and reactions. No *emote* output.
local _, addon = ...
local texts = addon.localeData.enUS.generalTexts
texts.RAISE = { gruppe = { "I have one more question.", "May I add something to that?" }, ziel = { "%s: May I add something to that?", "%s: I have one more question." } }
texts.RASP = { gruppe = { "That was my friendliest reply.", "My good manners have limits." }, ziel = { "%s: My good manners have limits.", "%s: That was my friendliest reply." } }
texts.READY = { gruppe = { "All prepared. I await your signal.", "The gear is secure and the decision is made." }, ziel = { "%s: The gear is secure and the decision is made.", "%s: All prepared. I await your signal." } }
texts.REAR = { gruppe = { "Apparently the horse has a speech to make.", "Easy, my friend. The road isn't going anywhere." }, ziel = { "%s: Easy, my friend. The road isn't going anywhere.", "%s: Apparently the horse has a speech to make." } }
texts.ROAR = { gruppe = { "Even the last enemy can hear me now!", "Some challenges deserve a proper roar." }, ziel = { "%s: Some challenges deserve a proper roar.", "%s: Even the last enemy can hear me now!" } }
texts.RUDE = { gruppe = { "Have you misplaced your manners somewhere?", "I find precious little to like about that behaviour." }, ziel = { "%s: I find precious little to like about that behaviour.", "%s: Have you misplaced your manners somewhere?" } }
texts.SCRATCH = { gruppe = { "All this dust is making me itch.", "Armour offers no protection against every tiny enemy." }, ziel = { "%s: Armour offers no protection against every tiny enemy.", "%s: All this dust is making me itch." } }
texts.SEXY = { gruppe = { "A little confidence never hurt anyone.", "Today I think I'll show my best side." }, ziel = { "%s: Today I think I'll show my best side.", "%s: A little confidence never hurt anyone." } }
texts.SHAKE = { gruppe = { "No, that won't get us anywhere.", "We need not agree to every absurd idea." }, ziel = { "%s: We need not agree to every absurd idea.", "%s: No, that won't get us anywhere." } }
texts.SHIMMY = { gruppe = { "You can hear a tune even without a band.", "My shoulders have found the rhythm." }, ziel = { "%s: My shoulders have found the rhythm.", "%s: You can hear a tune even without a band." } }
texts.SHIVER = { gruppe = { "A chill just ran down my spine.", "I doubt this is merely the weather." }, ziel = { "%s: I doubt this is merely the weather.", "%s: A chill just ran down my spine." } }
texts.SHOO = { gruppe = { "Shoo! There's nothing for you here!", "We could use a little peace and quiet." }, ziel = { "%s: We could use a little peace and quiet.", "%s: Shoo! There's nothing for you here!" } }
texts.SHY = { gruppe = { "I'm not used to so much attention.", "Perhaps we could start with an easier subject." }, ziel = { "%s: Perhaps we could start with an easier subject.", "%s: I'm not used to so much attention." } }
texts.SIGH = { gruppe = { "Some days demand more patience than others.", "Very well. Let us begin again." }, ziel = { "%s: Very well. Let us begin again.", "%s: Some days demand more patience than others." } }
texts.SLAP = { gruppe = { "That ought to get your attention back.", "A reminder with a little emphasis." }, ziel = { "%s: A reminder with a little emphasis.", "%s: That ought to get your attention back." } }
texts.SMELL = { gruppe = { "Something very good is cooking nearby.", "Or is that smoke? That would be less promising." }, ziel = { "%s: Or is that smoke? That would be less promising.", "%s: Something very good is cooking nearby." } }
texts.SMIRK = { gruppe = { "I know something you don't know yet.", "A small secret makes the day more interesting." }, ziel = { "%s: A small secret makes the day more interesting.", "%s: I know something you don't know yet." } }
texts.SNARL = { gruppe = { "The next step might be a mistake.", "Some boundaries are best left uncrossed." }, ziel = { "%s: Some boundaries are best left uncrossed.", "%s: The next step might be a mistake." } }
texts.SNICKER = { gruppe = { "I'm sure that wasn't the plan.", "I really am trying not to laugh." }, ziel = { "%s: I really am trying not to laugh.", "%s: I'm sure that wasn't the plan." } }
texts.SNIFF = { gruppe = { "That smells like the beginning of a story.", "My nose hasn't quite made up its mind." }, ziel = { "%s: My nose hasn't quite made up its mind.", "%s: That smells like the beginning of a story." } }
texts.SNUB = { gruppe = { "I have no appetite for that conversation today.", "Not every invitation deserves an answer." }, ziel = { "%s: Not every invitation deserves an answer.", "%s: I have no appetite for that conversation today." } }
texts.SOOTHE = { gruppe = { "Easy now. The danger has passed.", "Together we'll find our footing again." }, ziel = { "%s: Together we'll find our footing again.", "%s: Easy now. The danger has passed." } }
texts.SPIT = { gruppe = { "I won't miss that particular taste.", "Some things are best kept out of one's mouth." }, ziel = { "%s: Some things are best kept out of one's mouth.", "%s: I won't miss that particular taste." } }
texts.SPOON = { gruppe = { "A warm place is a good beginning.", "Company makes a cold evening easier." }, ziel = { "%s: Company makes a cold evening easier.", "%s: A warm place is a good beginning." } }
texts.STARE = { gruppe = { "That deserves a very long look.", "I am waiting for the sensible explanation." }, ziel = { "%s: I am waiting for the sensible explanation.", "%s: That deserves a very long look." } }
texts.STINK = { gruppe = { "Someone needs to open a window immediately.", "Whatever is lying there isn't fresh anymore." }, ziel = { "%s: Whatever is lying there isn't fresh anymore.", "%s: Someone needs to open a window immediately." } }
texts.STRONG = { gruppe = { "Together we can endure more than alone.", "Strength also means helping others." }, ziel = { "%s: Strength also means helping others.", "%s: Together we can endure more than alone." } }
texts.STRUT = { gruppe = { "Sometimes you ought to celebrate yourself.", "The next step deserves a triumphant bearing." }, ziel = { "%s: The next step deserves a triumphant bearing.", "%s: Sometimes you ought to celebrate yourself." } }
texts.SURRENDER = { gruppe = { "I am laying down my arms. For now.", "Another battle would help nobody." }, ziel = { "%s: Another battle would help nobody.", "%s: I am laying down my arms. For now." } }
texts.SURPRISED = { gruppe = { "That was not in our plans.", "Apparently there is always more to learn." }, ziel = { "%s: Apparently there is always more to learn.", "%s: That was not in our plans." } }
texts.TALK = { gruppe = { "A good conversation is worth a detour.", "Let's speak before we decide." }, ziel = { "%s: Let's speak before we decide.", "%s: A good conversation is worth a detour." } }
texts.TALKEX = { gruppe = { "I mean every single word!", "Sometimes a thought needs saying aloud." }, ziel = { "%s: Sometimes a thought needs saying aloud.", "%s: I mean every single word!" } }
texts.TALKQ = { gruppe = { "Could you explain that once more?", "I genuinely want to understand what you mean." }, ziel = { "%s: I genuinely want to understand what you mean.", "%s: Could you explain that once more?" } }
texts.TAP = { gruppe = { "My patience has developed an audible rhythm.", "Who said waiting was easy?" }, ziel = { "%s: Who said waiting was easy?", "%s: My patience has developed an audible rhythm." } }
texts.TAUNT = { gruppe = { "Come closer if you dare!", "I am far from finished with you." }, ziel = { "%s: I am far from finished with you.", "%s: Come closer if you dare!" } }
texts.TEASE = { gruppe = { "That was only a little joke at your expense.", "A little teasing keeps friends alert." }, ziel = { "%s: A little teasing keeps friends alert.", "%s: That was only a little joke at your expense." } }
texts.THIRSTY = { gruppe = { "A cool drink would be a blessing now.", "My throat feels like a desert." }, ziel = { "%s: My throat feels like a desert.", "%s: A cool drink would be a blessing now." } }
texts.THREAT = { gruppe = { "I will warn you only once.", "Do not put my patience to the test." }, ziel = { "%s: Do not put my patience to the test.", "%s: I will warn you only once." } }
texts.THREATEN = { gruppe = { "Your next step may prove costly.", "That warning was not for entertainment." }, ziel = { "%s: That warning was not for entertainment.", "%s: Your next step may prove costly." } }
texts.TICKLE = { gruppe = { "Even serious heroes have weaknesses.", "A little laughter can work wonders." }, ziel = { "%s: A little laughter can work wonders.", "%s: Even serious heroes have weaknesses." } }
texts.TIRED = { gruppe = { "My boots seem twice as heavy today.", "I need a bench, not another assignment." }, ziel = { "%s: I need a bench, not another assignment.", "%s: My boots seem twice as heavy today." } }
texts.TRAIN = { gruppe = { "Choo choo! Make way for the train!", "Who said heroes must always be serious?" }, ziel = { "%s: Who said heroes must always be serious?", "%s: Choo choo! Make way for the train!" } }
texts.VETO = { gruppe = { "I object to this plan in the strongest terms.", "Not every plan improves by being shouted." }, ziel = { "%s: Not every plan improves by being shouted.", "%s: I object to this plan in the strongest terms." } }
texts.VIOLIN = { gruppe = { "Alas, what a tragic fate.", "Shall I play an especially sad tune?" }, ziel = { "%s: Shall I play an especially sad tune?", "%s: Alas, what a tragic fate." } }
